        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            q=(r+dr,c+dc)
            if 0<=q[0]<H and 0<=q[1]<W and q not in S and q not in T and q in free and q not in dist:
                dist[q]=dist[(r,c)]+1; dq.append(q)
