    res=[]
    reached=set(dist.keys())
    for r,c in T:
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            q=(r+dr,c+dc)
            if 0<=q[0]<H and 0<=q[1]<W and q in free and q in reached:
                adj=q; break
        else: continue
        break
    cur=adj
    while dist.get(cur)<H*W-1 or True:
