               for d,[rr,cc] in [(dist.get((r+dr,c+dc),9999))] if False]
        # backtrack toward source using dist values
        curr=(r,c)
        dcurr=dist[curr]
        while dcurr>=0:
            res.append((curr[0],curr[1]))
            # move to neighbor with smaller dist
            moved=False
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                q=(curr[0]+dr,curr[1]+dc)
                if 0<=q[0]<H and 0<=q[1]<W and q in dist and dist[q]<dcurr:
                    curr=q; dcurr=dist[q]; moved=True; break
            if not moved: break
        break
