def f(inp):
    A=np.array(inp); H,W=A.shape; bg=int(A[0][0])
    cnt={k:[] for k in set(A.flatten())}
    for r in range(H):
        for c in range(W):
            cnt[A[r][c]].append((r,c))
    # smallest-count colors = the two dominoes
    scolors=sorted(cnt,key=lambda k:len(cnt[k]))
    S={(r,c) for r,c in cnt[scolors[0]]}; T={(r,c) for r,c in cnt[scolors[1]]}
