    dq=deque(); dist={}
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
        for r,c in S:
            q=(r+dr,c+dc)
            if 0<=q[0]<H and 0<=q[1]<W and q not in S and q not in T and q in free:
                if q not in dist: dist[q]=1; dq.append(q)
    while dq:
        r,c=dq.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            q=(r+dr,c+dc)
            if 0<=q[0]<H and 0<=q[1]<W and q not in S and q not in T and q in free and q not in dist:
                dist[q]=dist[(r,c)]+1; dq.append(q)
    # find first target-adjacent reached cell
    conn=None
    for r,c in T:
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            q=(r+dr,c+dc)
            if q in dist: conn=q; break
        if conn: break
    if conn is None: return out.tolist()
    # backtrack from conn toward source using dist
    res=[]
    cur=conn
    while True:
        res.append(cur)
        moves=[(cur[0]+dr,cur[1]+dc,dist.get((cur[0]+dr,cur[1]+dc),9e9)) for dr,dc in ((1,0),(-1,0),(0,1),(0,-1))]
        moves.sort(key=lambda m:m[2])
        if len(res)>1 and dist[cur]<=moves[0][2]: break
        cur=tuple(moves[0][:2]) if moves[0][2]<9e9 else break
        # stop when hitting src region or no better move
        if not any(0<=a<H and 0<=b<W and (a,b) in dist for a,b in [m[:2] for m in moves]): break
        cur=(moves[0][0],moves[0][1])
    out=res[-1][0][0]; 
    res.reverse()
    for r,c in res:
        out[r][c]=3
    return out.tolist()

