import numpy as np

def solve(inp):
    A=np.array(inp); H,W=A.shape
    cnt={k:[p for p in np.argwhere(A==k)] for k in set(A.flatten())}
    specials=sorted(cnt,key=lambda k:len(cnt[k]))
    S=set(map(tuple,specials[0])); T=set(map(tuple,specials[1]))
    bg=[k for k in cnt if len(cnt[k])>10][0]
    # find src/tgt: src = one that will be color of line; assume src=first, tgt=second
    O=A.copy()
    def free(p): return O[p]!=bg and O[p] not in (3,)
    dist={}
    dq=deque(); seen=set()
    for r,c in S:
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            q=(r+dr,c+dc)
            if 0<=q[0]<H and 0<=q[1]<W and not free(q) and q not in seen:
                dist[q]=1; seen.add(q); dq.append(q)
    while dq:
        r,c=dq.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            q=(r+dr,c+dc)
            if 0<=q[0]<H and 0<=q[1]<W and not free(q) and q not in seen:
                d=dist.get(q,999)+1
                if d<dist.get(q,99999): dist[q]=d; seen.add(q); dq.append(q)
    conn=None
    for r,c in T:
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            q=(r+dr,c+dc)
            if q in dist: conn=q; break
        if conn: break
    if conn is None: return O.tolist()
    res=[]; cur=conn
    while True:
        res.append(cur); dc=dist[cur]
        # move to neighbor with smallest dist (BFS backtrack)
        nb=[((cur[0]+a,cur[1]+b),dist.get((cur[0]+a,cur[1]+b),9999)) for a,b in ((1,0),(-1,0),(0,1),(0,-1))]
        nb.sort(key=lambda x:x[1]); nb=[(x[0],d) for x,d in nb if d<dc]
        if not nb or cur in S: break
        cur=min(nb,key=lambda x:x[1])[0]
    res.reverse()
    for r,c in res: O[r][c]=3
    return O.tolist()

