d=load()

def f(inp):
    A=[[int(x) for x in row] for row in inp]; H=len(A); W=len(A[0])
    cnt={}
    for r in range(H):
        for c in range(W):
            v=A[r][c]
            cnt.setdefault(v,[]).append((r,c))
    scolors=sorted(cnt,key=lambda k:len(cnt[k]))
    S=set(map(tuple,cnt[scolors[0]])); T=set(map(tuple,cnt[scolors[1]]))
    bg=max(cnt,key=lambda k:len(cnt[k]))
    free={(r,c) for r in range(H) for c in range(W) if A[r][c]==bg}
    dist={}; par={}; dq=deque()
    for s in S:
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            q=(s[0]+dr,s[1]+dc)
            if 0<=q[0]<H and 0<=q[1]<W and q not in S and q not in T and q in free and q not in dist:
                dist[q]=1; par[q]=s; dq.append(q)
    while dq:
        r,c=dq.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            q=(r+dr,c+dc)
            if 0<=q[0]<H and 0<=q[1]<W and q not in S and q not in T and q in free and q not in dist:
                dist[q]=dist[(r,c)]+1; par[q]=(r,c); dq.append(q)
    out=[[A[r][c] for c in range(W)] for r in range(H)]
    best=None
    for tc in T:
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            q=(tc[0]+dr,tc[1]+dc)
            if q in dist and (best is None or dist[q]<best[0]): best=(dist[q],q)
    cur=best[1] if best else None
    # walk parent pointers until hitting an S cell or missing entry
    while cur is not None:
        if cur not in S:
            out[cur[0]][cur[1]]=3
        cur=par.get(cur)
    return out

