d=load()

def solve(I):
    H,W=len(I),len(I[0])
    cnt={}
    for r in range(H):
        for c in range(W): cnt.setdefault(int(I[r][c]),[]).append((r,c))
    mc=sorted(cnt,key=lambda k:len(cnt[k]))
    S=cnt[mc[0]]; T=cnt[mc[1]]
    bg=max(cnt,key=lambda k:len(cnt[k]))
    free={(r,c) for r in range(H) for c in range(W) if I[r][c]==bg}
    # orientation: order cells so that path direction consistent: determine which end touches free space
    def ends(cells):
        rs=[a[0] for a in cells]; cs=[a[1] for a in cells]
        return [(min(rs),min(cs)),(max(rs),max(cs))]
    # anchor cells: first row of source domino (topmost-leftmost), last row of target (bottommost-rightmost)
    A_cell=sorted(S)[0]; B_cell=sorted(T)[-1]
    out=[[int(I[r][c]) for c in range(W)] for r in range(H)]
    # fill with bg color as starting values? no. draw: start neighbor of A going away
    cur=A_cell
    # try each direction from anchor until free
    best=None
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
        q=(cur[0]+dr,cur[1]+dc)
        if 0<=q[0]<H and 0<=q[1]<W and q in free:
            d3,BFSpar,q_=BFS_search(q,T,free,H,W); best=(d3,q_,BFSpar)
    dd,d0,bp=best
    cur=d0
    while cur is not None:
        out[cur[0]][cur[1]]=3
        cur=bp.get(cur)
    return out,mc,S,T,A_cell,B_cell,(A_cell,B_cell),best

def BFS_search(start,tset,free,H,W,par=None):
    par=par if par else {}
    dist={start:0}; dq=deque([start])
    while dq:
        r,c=dq.popleft()
        if (r,c) in tset: return dist[(r,c)],par
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            q=(r+dr,c+dc)
            if 0<=q[0]<H and 0<=q[1]<W and q not in tset and q in free and q not in dist:
                dist[q]=dist[(r,c)]+1; par[q]=(r,c); dq.append(q)
    return -1,{}

