    bg = cnt.most_common(1)[0][0]
    rare = [k for k in sorted(cnt, key=lambda k: cnt[k]) if cnt[k] > 1 and k != bg]
    src, tgt = rare[0], rare[1]
    S = [(int(r), int(c)) for r in range(H) for c in range(W) if int(I[r][c]) == src]
    T = [(int(r), int(c)) for r in range(H) for c in range(W) if int(I[r][c]) == tgt]
    obs = set(map(int, I.flatten())) - {bg, src, tgt}
    d = {}
    dq = collections.deque(S)
    for s in S: d[s] = 0
    while dq:
        r, c = dq.popleft()
        for dr, dc_ in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc_
            if 0 <= nr < H and 0 <= nc < W and int(I[nr][nc]) not in obs and (nr, nc) not in d:
                d[(nr, nc)] = d[(r, c)] + 1
                dq.append((nr, nc))
    best_tgt = min(T, key=lambda t: d.get(t, float('inf')))
    # backtrace from best tgt to src
    path = []
    cur = best_tgt
    while cur in d:
        path.append(cur)
        if cur in S: break
        prev = next(k for k, v in d.items() if k != cur and v == d[cur] - 1)
        cur = prev
    res = I.copy()
    for r, c in path:
        res[r][c] = tgt
    return res, (src, tgt)

