        print('idx',idx,'src',sc,'tgt-reach:',len(tgtlist),'maxdist',max(D.values()))
        if tgtlist:
            b=min(tgtlist,key=lambda tt:(D[tt],tt))
            o=A.copy(); cur=b; path=[]; prev=None
            while True:
                path.append(cur); o[cur[0]][cur[1]]=3
                if cur in srcset: break
                cand=[kk for kk,vv in D.items() if vv==D[cur]-1]
                if not cand: break
                def kf(k_):
                    s1=(prev is not None and prev[0]==cur[0]); s2=(prev is not None and prev[1]==cur[1])
                    return (-int(s1),-int(s2),abs(k_[0]-cur[0])+abs(k_[1]-cur[1]))
                prev=cur; cur=min(cand,kf)
            return (o,path,b,(srcset,tgtdom),len(path),idx,True)
    return None

for i in [1,2,3]:
    res=solve(d[f'Demo pair {i} input'])
    print(res)
